#[track_caller]
pub fn with_hints(mut self, new_hints: impl IntoIterator<Item = EcoString>) -> Self {
    let hints = self.hints_mut().expect("expected an error or warning");
    let iter = new_hints.into_iter().map(|h| (h, None));
    hints.extend(iter);
