        0,
        &|offset, len| Span::from_range(id, mapper.map(offset..offset + len)),
        &|offset, sub_range| {
            if let Some(sr) = sub_range {
                *sr = mapper.map_sub_range(offset, *sr);
            }
        },
        &|_, _| None,
    );
    Ok(())
}

